<?php require_once '../config/helpers.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$active=(int)($_POST['active']??0);$st=$pdo->prepare('UPDATE services SET is_active=? WHERE id=?');$st->execute([$active,$id]);flash('Service visibility updated.');redirect('services.php');}$services=$pdo->query('SELECT * FROM services ORDER BY id')->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/style.css"><title>Services</title></head><body><div class="admin-layout"><?php include '_nav.php'; ?><section class="admin-main"><h1>Manage Services</h1><?php show_flash(); ?><div class="grid"><?php foreach($services as $s): ?><article class="card"><h3><?= e($s['name']) ?></h3><p><?= e($s['description']) ?></p><p>Price: <?= (float)$s['price']>0?money($s['price']):'On enquiry' ?></p><p>Status: <span class="badge"><?= $s['is_active']?'Active':'Hidden' ?></span></p><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><input type="hidden" name="active" value="<?= $s['is_active']?0:1 ?>"><button class="btn secondary"><?= $s['is_active']?'Hide service':'Activate service' ?></button></form></article><?php endforeach; ?></div></section></div></body></html>
